 [('We ___ the mayor to retract his remarks. (urge)','urge','exortação.',None),('We call ___ all parties to adopt a code. (on)','on','phrasal.',None),('Insults ___ the norms of debate. (erode)','erode','verbo.',None),('It is not so much civility ___ accuracy. (as)','as','contraste.',None)],
 V('civic language=linguagem cívica|shared resource=recurso compartilhado|campaign etiquette pact=pacto de etiqueta de campanha|campaign rhetoric=retórica de campanha|heated remark=comentário inflamado|dehumanising label=rótulo desumanizador|insulting epithet=epíteto ofensivo|political vermin=tratamento de "pragas" políticas|traitor slur=insulto de traidor|withdrawn insult=insulto retirado|opponent smear=difamação do adversário|constitutional custom=costume constitucional|rival fear=medo do rival|speech standard=padrão de discurso|careful phrasing=formulação cuidadosa|public respect=respeito público|lost trust=confiança perdida|hard to win back=difícil de recuperar|call for restraint=apelo à moderação|leader-writing desk=mesa de editorialistas|opinion page=página de opinião|leader column=coluna do editorial|stern warning=advertência severa|hollow apology=desculpa vazia|fiery oratory=oratória inflamada|toxic discourse=discurso tóxico|civility pledge=compromisso de civilidade|accuracy over civility=precisão acima de cortesia|pointed rebuke=repreensão incisiva|rhetorical temperature=temperatura retórica'),
 ('Newsroom meeting',[('Editor','We urge the mayor to retract his remarks.','Instamos o prefeito a retratar seus comentários.'),('Writer','And we call on all parties to adopt a code of conduct.','E convocamos todos os partidos a adotar um código de conduta.'),('Editor','Add that heated rhetoric is part of democracy.','Acrescente que retórica acalorada faz parte da democracia.'),('Writer','But dehumanising rhetoric is a threat to it.','Mas a retórica desumanizadora é uma ameaça a ela.')]),
